// The same order model powers the playable preview and the regression checks.
export const freshBuild=()=>({confirm:false,dedupe:false,stock:false});
export const freshCafe=()=>({orders:[],seen:[],stock:{latte:3,croissant:0},notice:''});
export function placeOrder(build,cafe,item,request){
 if(build.dedupe&&cafe.seen.includes(request)){cafe.notice='Этот заказ уже принят.';return;}
 if(build.stock&&cafe.stock[item]<=0){cafe.notice='Закончилось. Выбери другой продукт.';return;}
 cafe.seen.push(request);const order={number:41+cafe.orders.length,item};cafe.orders.push(order);cafe.stock[item]--;cafe.notice=build.confirm?'Заказ №'+order.number+' принят. Забери у стойки.':'Нажатие обработано…';
}
export function checkBuild(build){
 const receipt=freshCafe();placeOrder(build,receipt,'latte','receipt');
 const twice=freshCafe();placeOrder(build,twice,'latte','same');placeOrder(build,twice,'latte','same');
 const empty=freshCafe();placeOrder(build,empty,'croissant','empty');
 return [receipt.notice.includes('№41'),twice.orders.length===1,empty.orders.length===0&&empty.stock.croissant===0];
}
export const createRelease=()=>({isolated:false,guard:false,dedupe:false,verified:false,deployed:false});
export function processTransfer(s,{amount,balance,key},seen=new Set()){if(s.guard&&(amount<=0||amount>balance))return 'rejected';if(s.dedupe&&seen.has(key))return 'duplicate';seen.add(key);return 'accepted';}
export function verifyRelease(s){const seen=new Set();return processTransfer(s,{amount:30,balance:100,key:'a'},seen)==='accepted'&&processTransfer(s,{amount:30,balance:100,key:'a'},seen)==='duplicate'&&processTransfer(s,{amount:200,balance:100,key:'b'},seen)==='rejected';}
export function mountDeveloper(host,onComplete,{checkpoint='start'}={}){
 const state=createRelease();let stage=0,selected=null,isolatedHits=0,raf,last=performance.now(),t=0,testTime=0,done=false,disposed=false;
 if(checkpoint!=='start'){state.isolated=true;stage=1;}if(checkpoint==='stock'){state.dedupe=true;}if(['fixed','tested'].includes(checkpoint)){state.guard=state.dedupe=true;stage=2;}if(checkpoint==='tested'){state.verified=true;stage=3;}
 host.innerHTML=`<section class="release-game"><header><div><span>ЦЕНТР ИНВЕСТ БАНК / RELEASE CONTROL</span><h2>Остановить каскадный сбой.</h2></div><b class="release-live">● ИНЦИДЕНТ В СЕТИ</b></header><div class="release-steps"><span>01 ИЗОЛЯЦИЯ</span><span>02 ПАТЧ</span><span>03 ТЕСТ</span><span>04 РЕЛИЗ</span></div><div class="release-arena"><canvas aria-label="Поток переводов и сбойных пакетов"></canvas><div class="release-core"><span>₽</span><b>ПЛАТЁЖНЫЙ ШЛЮЗ</b><small class="release-core-status">ПОВТОРНЫЕ СПИСАНИЯ</small></div><div class="release-packets"></div><div class="release-nodes"><button data-node="dedupe"><i>↻</i><b>Повторный перевод</b><small>Уже принят → не списывать дважды</small></button><button data-node="guard"><i>₽</i><b>Недопустимая сумма</b><small>Выше баланса → отклонить</small></button></div></div><div class="release-console"><div><span class="release-stage"></span><h3 class="release-task"></h3><p class="release-status" role="status"></p></div><div class="release-tools"><button data-patch="dedupe">↻ Защита от дублей</button><button data-patch="guard">₽ Проверка баланса</button><button id="release-test">▶ Прогнать переводы</button><button id="release-deploy">↑ Выпустить патч</button></div></div><div class="release-results"></div></section>`;
 const q=x=>host.querySelector(x),canvas=q('canvas'),ctx=canvas.getContext('2d');
 function sync(){const titles=['Поймай 3 красных сбойных пакета','Подключи два защитных модуля','Прогони тестовые переводы','Выпусти исправление в сеть'];q('.release-stage').textContent='ШАГ '+(stage+1)+' / 4';q('.release-task').textContent=titles[stage];q('.release-status').textContent=stage===0?'Нажимай только красные пакеты. Зелёные — обычные переводы. '+isolatedHits+'/3':stage===1?'Выбери модуль внизу, затем соответствующий узел над ним.':stage===2?'Проверяем обычный перевод, повтор и сумму выше баланса.':'Проверки пройдены. Можно переключить сервис на новую версию.';host.querySelectorAll('.release-steps span').forEach((e,i)=>e.classList.toggle('active',i===stage));host.querySelectorAll('[data-patch]').forEach(e=>{e.disabled=stage!==1||state[e.dataset.patch];e.classList.toggle('selected',selected===e.dataset.patch);});host.querySelectorAll('[data-node]').forEach(e=>{e.disabled=stage!==1;e.classList.toggle('patched',state[e.dataset.node]);});q('#release-test').hidden=stage!==2;q('#release-deploy').hidden=stage!==3;q('.release-packets').hidden=stage!==0;}
 const packets=Array.from({length:8},(_,i)=>{const b=document.createElement('button');const bad=i%3!==0;b.className='transfer-packet '+(bad?'bad':'good');b.textContent=bad?'! ДУБЛЬ':'✓ ПЕРЕВОД';b.setAttribute('aria-label',bad?'Изолировать сбойный пакет '+i:'Обычный перевод '+i);b.onpointerenter=()=>b.dataset.hover='1';b.onpointerleave=()=>b.dataset.hover='';b.onclick=()=>{if(stage!==0||b.disabled)return;if(!bad){q('.release-status').textContent='Это обычный перевод — сохрани его маршрут.';return;}b.disabled=true;b.style.opacity=0;isolatedHits++;if(isolatedHits===3){state.isolated=true;stage=1;q('.release-core-status').textContent='СБОЙНЫЙ МОДУЛЬ ИЗОЛИРОВАН';}sync();};q('.release-packets').append(b);return b;});
 host.querySelectorAll('[data-patch]').forEach(b=>b.onclick=()=>{selected=b.dataset.patch;sync();});host.querySelectorAll('[data-node]').forEach(b=>b.onclick=()=>{if(selected!==b.dataset.node){q('.release-status').textContent='Сопоставь модуль и проблему по символу и названию.';return;}state[selected]=true;selected=null;if(state.guard&&state.dedupe)stage=2;sync();});
 q('#release-test').onclick=()=>{if(testTime)return;testTime=.001;q('#release-test').disabled=true;q('.release-status').textContent='Идёт прогон: реальные правила обрабатывают три сценария…';};
 q('#release-deploy').onclick=()=>{if(done||!state.verified)return;done=true;state.deployed=true;q('.release-live').textContent='● СЕРВИС ВОССТАНОВЛЕН';q('.release-core-status').textContent='НОВАЯ ВЕРСИЯ / HEALTHY';q('.release-task').textContent='Патч в работе. Переводы защищены.';q('.release-status').textContent='Ты изолировал сбой, добавил проверку баланса и защиту от повторного списания, проверил поведение и выпустил новую версию. Это цикл работы разработчика при инциденте.';q('#release-deploy').disabled=true;onComplete();};
 function frame(now){if(disposed)return;raf=requestAnimationFrame(frame);const dt=Math.min(.05,(now-last)/1000);last=now;if(document.hidden||host.dataset.paused==='true')return;t+=dt;const w=canvas.clientWidth,h=canvas.clientHeight;if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;}ctx.clearRect(0,0,w,h);ctx.strokeStyle='#9b8acd28';for(let i=0;i<9;i++){ctx.beginPath();ctx.moveTo(0,h*i/8);ctx.lineTo(w,h*i/8);ctx.stroke();}for(let i=0;i<30;i++){const x=((t*75+i*71)%(w+40))-20,y=h*(.18+(i%5)*.14);ctx.fillStyle=stage===0&&i%3?'#f36d74':'#9ae3bd';ctx.fillRect(x,y,9,3);}packets.forEach((b,i)=>{if(b.dataset.hover)return;b.style.left=(8+i*10+Math.sin(t*.7+i)*1.2)+'%';b.style.top=(12+(i%3)*21)+'%';});if(testTime){testTime+=dt;if(testTime>=3){testTime=0;state.verified=verifyRelease(state);q('.release-results').innerHTML='<span>✓ Обычный перевод принят</span><span>✓ Повтор не списывает деньги</span><span>✓ Превышение баланса отклонено</span>';if(state.verified)stage=3;sync();}}}
 sync();raf=requestAnimationFrame(frame);return()=>{disposed=true;cancelAnimationFrame(raf);};
}
